    36  type IOURequestStepWaypointOnyxProps = {
    37      /** List of recent waypoints */
    38      recentWaypoints: OnyxEntry<Place[]>;
    39
    40      userLocation: OnyxEntry<OnyxTypes.UserLocation>;
    41  };
    42
    43  type IOURequestStepWaypointProps = IOURequestStepWaypointOnyxProps &
    44      WithWritableReportOrNotFoundProps<typeof SCREENS.MONEY_REQUEST.STEP_WAYPOINT> & {
    45          transaction: OnyxEntry<OnyxTypes.Transaction>;
    46      };
